  // Rally Sync (Tools → Rally Sync): rooms where rally leaders get their own start time so every rally lands at the same second
  "sync.title": { en: "Rally Sync", de: "Rally-Sync", ko: "집결 동기화", pl: "Rally Sync", ar: "مزامنة الحشود" },
  "sync.subtitle": {
    en: "Every rally lands at the same second. Each rally leader gets their own UTC start time, worked out from their march time.",
    de: "Alle Rallys schlagen in derselben Sekunde ein. Jeder Rally-Leiter bekommt seine eigene UTC-Startzeit, berechnet aus seiner Marschzeit.",
    ko: "모든 집결이 같은 초에 도착합니다. 집결 대장마다 행군 시간으로 계산한 UTC 출발 시간이 주어집니다.",
    pl: "Wszystkie rajdy uderzają w tej samej sekundzie. Każdy lider rajdu dostaje własny czas startu w UTC, obliczony z czasu marszu.",
    ar: "تصل كل الحشود في الثانية نفسها. يحصل كل قائد حشد على وقت بدء خاص به بتوقيت UTC محسوب من زمن مسيرته.",
  },
  "sync.roomSubtitle": {
    en: "Start your rally when the in-game clock shows your start time.",
    de: "Starte deine Rally, wenn die Spieluhr deine Startzeit zeigt.",
    ko: "게임 내 시계가 출발 시간을 가리킬 때 집결을 시작하세요.",
    pl: "Rozpocznij rajd, gdy zegar w grze pokaże twój czas startu.",
    ar: "ابدأ حشدك عندما تعرض ساعة اللعبة وقت البدء الخاص بك.",
  },
